WITH kept_keys AS (SELECT id, promo_code FROM promotions EXCEPT ALL SELECT id, promo_code FROM promotions WHERE promo_code IN ('SPRING10', 'WELCOME5')), kept_rows AS (SELECT s.* FROM promotions s INNER JOIN kept_keys k ON s.id = k.id AND s.promo_code = k.promo_code) SELECT CASE WHEN discount_pct >= 0.35 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, DATE_TRUNC('WEEK', starts_on) AS week_start, PERCENTILE_APPROX(discount_pct, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_quartiles, SORT_ARRAY(COLLECT_SET(promo_code)) AS promo_code_list, SORT_ARRAY(COLLECT_SET(promo_code)) AS promo_code_list_2 FROM kept_rows GROUP BY 1, 2
